<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import type { ConfiguracionRetencion,ConfiguracionRetencionPayload } from '../interfaces/configuracion-retencion.interface'
import { cambiarEstadoConfiguracionRetencion,guardarConfiguracionRetencion,listarConfiguracionesRetencion,obtenerConfiguracionRetencion } from '../services/configuracion-retencion'
const blank=():ConfiguracionRetencionPayload=>({descripcion:'',porcentaje:0,monto_minimo:null,serie:'',correlativo_actual:0,longitud_correlativo:8,vigente_desde:'',vigente_hasta:''})
const rows=ref<ConfiguracionRetencion[]>([]),buscar=ref(''),estado=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),showForm=ref(false),editing=ref<number|null>(null),form=reactive(blank())
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',date=(v?:string|null)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'Indefinida',money=(v?:number|null)=>v==null?'-':new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v)
const nextNumber=computed(()=>`${form.serie}-${String(form.correlativo_actual+1).padStart(form.longitud_correlativo,'0')}`)
async function load(next=1){loading.value=true;error.value='';try{const r=await listarConfiguracionesRetencion(buscar.value,estado.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function create(){editing.value=null;Object.assign(form,blank());showForm.value=true}
async function edit(item:ConfiguracionRetencion){loading.value=true;try{const x=await obtenerConfiguracionRetencion(item.id);editing.value=x.id;Object.assign(form,blank(),x,{monto_minimo:x.monto_minimo??null,vigente_desde:x.vigente_desde?.slice(0,10)||'',vigente_hasta:x.vigente_hasta?.slice(0,10)||''});showForm.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){if(form.vigente_hasta&&form.vigente_desde>form.vigente_hasta){error.value='La fecha final no puede ser menor que la fecha inicial.';return}loading.value=true;error.value='';try{await guardarConfiguracionRetencion(editing.value,{...form});success.value=`Configuración ${editing.value?'actualizada':'registrada'} correctamente.`;showForm.value=false;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function toggle(item:ConfiguracionRetencion){const action=item.activo?'inactivar':'activar';if(!confirm(`¿Desea ${action} la configuración ${item.serie}?`))return;loading.value=true;try{await cambiarEstadoConfiguracionRetencion(item.id);success.value=`Configuración ${item.activo?'inactivada':'activada'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){buscar.value='';estado.value='';load(1)}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Configuración de retenciones</nav><header class="hero"><div class="mark">RT</div><div><small>MIA · FINANZAS · MAESTROS</small><h1>Configuración de retenciones</h1><p>Porcentajes, montos y numeración de comprobantes de retención.</p></div><strong>{{total}} configuraciones</strong><button @click="create">+ Nueva configuración</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="buscar" placeholder="Buscar por descripción o serie"><select v-model="estado"><option value="">Todos los estados</option><option value="1">Activos</option><option value="0">Inactivos</option></select><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron configuraciones.</div><div v-else class="scroll"><table><thead><tr><th>Descripción</th><th>Retención</th><th>Serie</th><th>Correlativo actual</th><th>Siguiente comprobante</th><th>Vigencia</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.descripcion}}</b><small>Mínimo: {{money(item.monto_minimo)}}</small></td><td><b>{{Number(item.porcentaje).toFixed(4)}}%</b></td><td>{{item.serie}}</td><td>{{String(item.correlativo_actual).padStart(item.longitud_correlativo,'0')}}</td><td><b>{{item.siguiente_correlativo_texto||`${item.serie}-${String(item.correlativo_actual+1).padStart(item.longitud_correlativo,'0')}`}}</b></td><td>{{date(item.vigente_desde)}}<small>hasta {{date(item.vigente_hasta)}}</small></td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVO':'INACTIVO'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Inactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVA CONFIGURACIÓN'}}</small><h2>{{editing?'Editar':'Registrar'}} retención</h2></div><button type="button" @click="showForm=false">×</button></header><div class="grid"><label class="span2">Descripción<input v-model.trim="form.descripcion" maxlength="150" required></label><label>Porcentaje<input v-model.number="form.porcentaje" type="number" min="0.0001" max="100" step="0.0001" required></label><label>Monto mínimo<input v-model.number="form.monto_minimo" type="number" min="0" step="0.0001"></label><label>Serie<input v-model.trim="form.serie" maxlength="20" required></label><label>Correlativo actual<input v-model.number="form.correlativo_actual" type="number" min="0" step="1" required></label><label>Longitud del correlativo<input v-model.number="form.longitud_correlativo" type="number" min="1" max="20" required></label><label class="preview">Siguiente número<b>{{nextNumber}}</b></label><label>Vigente desde<input v-model="form.vigente_desde" type="date" required></label><label>Vigente hasta<input v-model="form.vigente_hasta" type="date"></label></div><p class="notice">La vigencia no debe superponerse con otra configuración activa.</p><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small{color:var(--a);font-size:.5rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:2fr 1fr auto auto;gap:7px;background:#fff}.filters input,.filters select,.dialog input{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.52rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1080px;border-collapse:collapse;font-size:.5rem}th,td{padding:10px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#829096}.good,.bad{display:inline-block;padding:4px 8px;border-radius:10px;font-size:.47rem;font-weight:800}.good{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.actions{display:flex;gap:5px}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:45px;text-align:center}.card>footer,.dialog>footer{padding:12px;display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(720px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.grid label{display:grid;gap:5px;color:#5d7078;font-size:.52rem;font-weight:700}.span2{grid-column:span 2}.preview{padding:8px;border-radius:6px;background:#edf6f7}.preview b{color:var(--a);font-size:.65rem}.notice{padding:9px;color:#795c1c;background:#fff5d9;font-size:.5rem}@media(max-width:650px){.filters,.grid{grid-template-columns:1fr}.span2{grid-column:auto}.hero{align-items:flex-start;flex-wrap:wrap}.hero .mark{display:none}}
</style>
